class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        int best = 0;
        for (int x : s) {
            if (s.find(x - 1) == s.end()) {          // x is a potential start
                int cur = x;
                while (s.find(cur + 1) != s.end()) ++cur;
                best = max(best, cur - x + 1);
            }
        }
        return best;
    }
};
